/* MUTANT: one refusal broken on purpose. The gate MUST go red against this
 * file. Generated by mut/make.py; never edited by hand.
 */
/* <ov-station> - an absence is not the phenomenon being absent.
 *
 * For terminal,
 * industrial, antiseptic and aegis. One tile per element of a surface
 * observation (wind, visibility, present weather, cloud, temperature,
 * pressure, lightning, freezing rain, RVR), each carrying HOW it was derived
 * (automated, augmented by an observer, or manual) and, when it is absent,
 * WHICH KIND of absence.
 *
 *   <ov-station label="KXYZ" method="automated" max-age="3600"
 *               elements="wind, visibility, cloud, temperature, lightning, rvr">
 *   </ov-station>
 *   st.observation = {
 *     age: 120, method: 'automated', maintenance: false,
 *     equipment: ['wind', 'visibility', 'cloud', 'temperature', 'rvr'],
 *     elements: [{ name: 'wind', value: '240/08', unit: 'kt' },
 *                { name: 'cloud', detected: false },
 *                { name: 'rvr', operating: false }],
 *   };
 *
 * ── THE REFUSAL ───────────────────────────────────────────────────────────
 *
 * 🔴 FOUR KINDS OF NOTHING, NEVER COLLAPSED INTO ONE.
 *
 *   NOT EQUIPPED      the station has no such sensor. Its silence says
 *                     nothing about the weather at all.
 *   NOT OPERATING     equipped, and the sensor is down (the METAR remarks
 *                     TSNO, PWINO, PNO, FZRANO, VISNO, CHINO, RVRNO).
 *   UNABLE TO DETECT  running, and this class is beyond it: CAP 746 §4.147,
 *                     an automatic system "unable to detect towering cumulus
 *                     or cumulonimbus ... shall be indicated by three slashes
 *                     (///)". The `incapable` reason.
 *   DETECTED NONE     running, capable, and it looked: nothing there.
 *
 * And three that follow:
 *
 * 1. AN AUTOMATIC "NONE" IS NOT A HUMAN "CLEAR". CAP 746 §4.102: "NCD ... is
 *    ONLY reported by automatic observing systems to indicate that no clouds
 *    are detected by the system", while JO 7900.5E's glossary keeps "SKC sky
 *    clear (manual observation)" apart. A machine's empty sky reads NO CLOUD
 *    DETECTED · NCD; only a human's reads SKY CLEAR.
 * 2. WITHOUT THE EQUIPMENT LIST, AN ABSENCE CANNOT BE READ AT ALL. JO 7900.5E
 *    §13.57 codes TSNO only at stations "equipped with" a lightning sensor, so
 *    an unequipped station's silence about thunder looks exactly like no
 *    thunder. With no `equipment` declared the element refuses to call any
 *    empty element DETECTED NONE: ABSENCE UNREADABLE.
 * 3. NO MAINTENANCE FLAG IS NOT HEALTHY. JO 7900.5E §13.58: "While the $ sign
 *    indicates there is an internal problem with the automated weather system,
 *    not all problems are self-detected." So a station with no flag says NO
 *    MAINTENANCE FLAG, never OK; a missing flag field says NOT REPORTED.
 *
 * A whole report of slashes (CAP 746 §4.146, "//////") is every element NOT
 * OPERATING: the header then reads STATION NOT OPERATING, and no element is
 * read as an observation.
 *
 * No `role="img"`: the tiles must reach a screen reader.
 * Redrawn on each observation and at most once a second while on screen, for
 * the report's age. Nothing runs every frame.
 *
 * The equipment-list rule is this element's own, not a quoted standard.
 */

import { define, watchSeen, isSeen, whenArrived } from '../../../src/ov-core.js';
import '../../../src/ov-source.js';

const KNOWN = ['wind', 'visibility', 'weather', 'cloud', 'temperature', 'dewpoint', 'pressure',
  'lightning', 'freezing-rain', 'rvr'];

const WORD = {
  value: null,
  none: 'DETECTED NONE',
  ncd: 'NO CLOUD DETECTED',
  clear: 'SKY CLEAR',
  'not-equipped': 'NOT EQUIPPED',
  'not-operating': 'NOT OPERATING',
  incapable: 'UNABLE TO DETECT',
  unreadable: 'ABSENCE UNREADABLE',
  'not-reported': 'NOT REPORTED',
};
const WHY = {
  'not-equipped': 'no such sensor here: its silence says nothing about the weather',
  'not-operating': 'equipped, and the sensor is down',
  incapable: 'running, and this class is beyond it',
  none: 'looked, and found none',
  ncd: 'no cloud detected by the system; not a human sky clear',
  clear: 'observed clear by a person',
  unreadable: 'no equipment list: an unequipped station\'s silence looks the same as nothing detected',
  'not-reported': 'nothing said about it in this report',
};
const HOW = { automated: 'AUTO', augmented: 'AUG', manual: 'MAN' };

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const setText = (el, t) => { if (el && el.textContent !== t) el.textContent = t; };
const setAttr = (el, k, v) => {
  if (!el) return;
  if (v === null) { if (el.hasAttribute(k)) el.removeAttribute(k); } else if (el.getAttribute(k) !== v) el.setAttribute(k, v);
};
const num = (raw) => (raw === null || raw.trim() === '' ? null : Number(raw));
const finite = (v) => v !== null && Number.isFinite(v);
const span = (s) => {
  const n = Math.floor(s);
  if (n < 60) return `${n}s`;
  if (n < 3600) return `${Math.floor(n / 60)}m`;
  return `${Math.floor(n / 3600)}h ${String(Math.floor(n / 60) % 60).padStart(2, '0')}m`;
};

/* One glyph per element, drawn from the same 24x24 box. A tile that cannot
 * report draws the glyph faint and puts its own mark over it, so the kind of
 * absence is a SHAPE as well as a word. */
const GLYPH = {
  wind: '<path d="M3 9h12a3 3 0 1 0-3-3"/><path d="M3 14h15a3 3 0 1 1-3 3"/>',
  visibility: '<path d="M2 12h7"/><path d="M11 12h4" opacity=".6"/><path d="M17 12h2" opacity=".3"/><circle cx="21" cy="12" r="1.4" opacity=".3"/>',
  weather: '<circle cx="8" cy="8" r="1.4"/><circle cx="14" cy="11" r="1.4"/><circle cx="9" cy="15" r="1.4"/><circle cx="16" cy="17" r="1.4"/>',
  cloud: '<path d="M4 9h13"/><path d="M6 13h12"/><path d="M8 17h9"/>',
  temperature: '<path d="M12 3v11"/><circle cx="12" cy="18" r="3.2"/>',
  dewpoint: '<path d="M12 3c4 6 5 8 5 10a5 5 0 0 1-10 0c0-2 1-4 5-10z"/>',
  pressure: '<path d="M4 17a9 9 0 0 1 16 0"/><path d="M12 17l5-6"/>',
  lightning: '<path d="M13 2 6 13h5l-2 9 8-12h-5z"/>',
  'freezing-rain': '<path d="M12 3v10M8 5l8 6M16 5l-8 6"/><path d="M10 20l2-3 2 3"/>',
  rvr: '<path d="M7 21 11 3M17 21 13 3"/><path d="M9 15h6M10 10h4"/>',
};

let serial = 0;

class OvStation extends HTMLElement {
  static observedAttributes = ['src', 'label', 'method', 'elements', 'max-age', 'source'];
  static now = () => Date.now();

  constructor() {
    super();
    this._obs = undefined;
    this._at = null;
    this._rows = [];
    this._queue = [];
    this._seen = new Map();     // element name -> last state, for transitions
    this._uid = `ov-station-${++serial}`;
  }

  connectedCallback() {
    if (!this._built) this.build();
    this.fetchSrc();
    this.bindSource();
    this.render();
    // 🔴 A LIVE LOOP WAITS FOR THE PAGE. ov-core holds every feed, frame and
    // timer until the first screenful has landed, so the tick is started
    // through whenArrived rather than here; it fires at once on an element
    // upgraded after arrival, which is what lazy loading makes of this one.
    if (!this._unarrive) this._unarrive = whenArrived(() => this.startTicking());
    if (!this._unwatch) this._unwatch = watchSeen(this, () => this.render());
  }

  startTicking() {
    if (this._timer || !this.isConnected) return;
    this._timer = setInterval(() => { if (isSeen(this)) this.render(); }, 1000);
  }

  disconnectedCallback() {
    clearInterval(this._timer);
    this._timer = 0;
    if (this._unarrive) this._unarrive();
    this._unarrive = null;
    if (this._unwatch) this._unwatch();
    this._unwatch = null;
    if (this.unsub) this.unsub();
    this.unsub = null;
  }

  attributeChangedCallback(name) {
    if (!this._built) return;
    if (name === 'src') { this.fetchSrc(); return; }
    if (name === 'source') this.bindSource();
    this.render();
  }

  /* A scene from a file, so the element renders as plain markup on a page that
   * carries no script: `<ov-station src="models/station-x.json">`. The same
   * route the kit's other data-driven elements take (ov-consistency,
   * ov-coverage), and the reason a reference page can show one at all.
   *
   * 🔴 A FETCH THAT FAILS LEAVES NO SCENE, NOT A STALE ONE. The element then
   * says what it says with no data, which is its own refusal rather than the
   * last thing that happened to load. The src check after the await is for a
   * src changed while the request was in flight: the loser must not win.
   */
  async fetchSrc() {
    const src = this.getAttribute('src');
    if (!src) return;
    let data = null;
    try {
      const r = await fetch(src);
      if (!r.ok) throw new Error(String(r.status));
      data = await r.json();
    } catch {
      data = null;
    }
    if (this.getAttribute('src') !== src) return;
    this.observation = data;
  }

  bindSource() {
    if (this.unsub) this.unsub();
    this.unsub = null;
    const name = this.getAttribute('source');
    if (!name || !window.Overscan?.subscribe) return;
    this.unsub = window.Overscan.subscribe(name, (o) => { this.observation = o; });
  }

  set observation(o) {
    this._obs = o;
    this._at = OvStation.now();
    this.render();
  }

  get observation() { return this._obs; }

  /* What each declared element is, and why. The order is the order declared:
   * a missing element keeps its place, because a gap that closes up reads as
   * an element nobody asked for. */
  read() {
    const o = this._obs;
    const declared = (this.getAttribute('elements') || KNOWN.join(', ')).split(',').map((s) => s.trim()).filter(Boolean);
    const stationMethod = (o && o.method) || this.getAttribute('method') || 'automated';
    const equipment = o && Array.isArray(o.equipment) ? o.equipment.map((s) => String(s).trim()) : null;
    const byName = new Map((o && Array.isArray(o.elements) ? o.elements : [])
      .filter((e) => e && typeof e === 'object' && e.name)
      .map((e) => [String(e.name).trim(), e]));
    return declared.map((name) => {
      const e = byName.get(name) || {};
      const how = e.method || stationMethod;
      const equipped = equipment ? equipment.includes(name) : null;
      let state;
      if (equipped === false) state = 'not-equipped';
      else if (e.operating === false) state = 'not-operating';
      else if (e.capable === false) state = 'incapable';
      else if (e.value !== undefined && e.value !== null && e.value !== '') state = 'value';
      else if (e.detected === false) {
        // A machine's "none" and a person's "clear" are different claims, and
        // neither can be read without knowing the station is equipped.
        state = 'none';  // MUTANT: absent means absent
      } else state = 'not-reported';
      return { name, e, how, equipped, state };
    });
  }

  render() {
    if (!this._built) return;
    const o = this._obs;
    const rows = this.read();
    const now = OvStation.now();
    const maxAge = num(this.getAttribute('max-age'));
    // 🔴 `age: null` is "no time given", not zero. Number(null) is 0, so the
    // first cut showed a report with no time as 0s OLD: the freshest reading
    // possible, invented from nothing (the kit's undefined/null rule,
    // ov-refusal.js).
    const rawAge = o ? o.age : undefined;
    const age = rawAge !== null && rawAge !== undefined && Number.isFinite(Number(rawAge))
      ? Number(rawAge) + (now - this._at) / 1000 : null;
    const stale = finite(maxAge) && age !== null && age > maxAge;
    const down = rows.length > 0 && rows.every((r) => r.state === 'not-operating');
    const method = (o && o.method) || this.getAttribute('method') || 'automated';

    setAttr(this, 'data-ov-station', o === undefined ? 'none' : down ? 'down' : stale ? 'stale' : 'reporting');
    setAttr(this, 'data-ov-refusal', o === undefined || down ? 'unknown' : null);
    setAttr(this, 'data-ov-qualified', !down && stale ? 'stale' : null);
    setText(this.querySelector('.ov-station__label'), this.getAttribute('label') || 'STATION');
    setText(this.querySelector('.ov-station__how'), `${method.toUpperCase()}${o && o.equipment ? '' : ' · NO EQUIPMENT LIST'}`);
    setText(this.querySelector('.ov-station__age'), o === undefined ? 'NO REPORT'
      : age === null ? 'REPORT TIME NOT GIVEN' : `${span(age)} OLD${stale ? ` · OVER ${span(maxAge)}` : ''}`);

    // The maintenance flag, and what its absence does NOT mean.
    const m = o ? o.maintenance : undefined;
    const maint = o === undefined ? '' : m === true ? 'MAINTENANCE NEEDED ($)'
      : m === false ? 'NO MAINTENANCE FLAG · not a health check: not all problems are self-detected'
        : 'MAINTENANCE FLAG NOT REPORTED';
    setText(this.querySelector('.ov-station__maint'), maint);
    setAttr(this.querySelector('.ov-station__maint'), 'data-ov-maint', o === undefined ? null : m === true ? 'needed' : m === false ? 'unflagged' : 'unknown');
    setText(this.querySelector('.ov-station__down'), down ? 'STATION NOT OPERATING · no element of this report is an observation' : '');

    this.paintTiles(rows, down);
    this._rows = rows;

    // A sensor that goes down, or comes back, is announced once.
    for (const r of rows) {
      const was = this._seen.get(r.name);
      if (was !== undefined && was !== r.state && (r.state === 'not-operating' || was === 'not-operating')) {
        this.say(`${r.name} ${r.state === 'not-operating' ? 'sensor not operating' : `back, ${(WORD[r.state] || 'reporting').toLowerCase()}`}`);
      }
      this._seen.set(r.name, r.state);
    }
    this.dispatchEvent(new CustomEvent('ov:station', { bubbles: true, detail: this.report }));
  }

  paintTiles(rows, down) {
    const list = this.querySelector('.ov-station__tiles');
    const key = rows.map((r) => r.name).join('');
    if (this._key !== key) {
      this._key = key;
      list.innerHTML = rows.map((r) => `
        <li class="ov-station__tile" data-ov-element="${esc(r.name)}">
          <svg class="ov-station__glyph" viewBox="0 0 24 24" aria-hidden="true">
            <g class="ov-station__art">${GLYPH[r.name] || '<rect x="4" y="4" width="16" height="16"/>'}</g>
            <g class="ov-station__mark"></g>
          </svg>
          <span class="ov-station__name">${esc(r.name.replace('-', ' '))}</span>
          <span class="ov-station__read"></span>
          <span class="ov-station__how2"></span>
          <span class="ov-station__why"></span>
        </li>`).join('');
    }
    rows.forEach((r, i) => {
      const li = list.children[i];
      const e = r.e;
      setAttr(li, 'data-ov-state', r.state);
      const read = r.state === 'value' ? `${e.value}${e.unit ? ' ' + e.unit : ''}` : WORD[r.state];
      setText(li.querySelector('.ov-station__read'), read);
      setText(li.querySelector('.ov-station__how2'), r.state === 'value' || r.state === 'none' || r.state === 'ncd' || r.state === 'clear' ? HOW[r.how] || r.how.toUpperCase() : '');
      const why = r.state === 'value' ? (e.note || '') : (e.note || WHY[r.state] || '');
      setText(li.querySelector('.ov-station__why'), down && r.state === 'not-operating' ? 'whole report is slashes' : why);
      // The mark over the glyph: a shape per kind of absence.
      const mark = {
        'not-equipped': '<line x1="3" y1="21" x2="21" y2="3"/><line x1="3" y1="3" x2="21" y2="21"/>',
        'not-operating': '<line x1="4" y1="20" x2="20" y2="4"/>',
        incapable: '<line x1="6" y1="20" x2="11" y2="4"/><line x1="11" y1="20" x2="16" y2="4"/><line x1="16" y1="20" x2="21" y2="4"/>',
        unreadable: '<circle cx="12" cy="12" r="9" stroke-dasharray="3 3"/>',
        'not-reported': '<circle cx="12" cy="12" r="9" stroke-dasharray="1 4"/>',
      }[r.state] || '';
      const g = li.querySelector('.ov-station__mark');
      if (g.innerHTML !== mark) g.innerHTML = mark;
      li.setAttribute('aria-label', `${r.name.replace('-', ' ')}: ${read}${why ? ', ' + why : ''}`);
    });
  }

  get report() {
    return {
      station: this.getAttribute('label'),
      state: this.getAttribute('data-ov-station'),
      elements: this._rows.map((r) => ({ name: r.name, state: r.state, value: r.state === 'value' ? r.e.value : null, method: r.how })),
    };
  }

  say(text) {
    this._queue.push(text);
    if (this._flushing) return;
    this._flushing = true;
    queueMicrotask(() => {
      this._flushing = false;
      const t = this._queue.join('; ');
      this._queue = [];
      const region = this.querySelector('.ov-station__say');
      if (region) { region.textContent = ''; region.textContent = t; }
    });
  }

  build() {
    this._built = true;
    this.innerHTML = `
      <div class="ov-head ov-head--tight">
        <span class="ov-aside ov-station__label"></span>
        <span class="ov-station__how"></span>
        <span class="ov-station__age"></span>
      </div>
      <div class="ov-station__down"></div>
      <ol class="ov-station__tiles"></ol>
      <div class="ov-station__maint"></div>
      <div class="ov-station__say" aria-live="polite"></div>`;
    this.setAttribute('role', 'group');
    if (!this.hasAttribute('aria-label')) this.setAttribute('aria-label', `${this.getAttribute('label') || 'station'} observation`);
  }
}

define('ov-station', OvStation);

export { OvStation };
